private static Charset charsetFromMediaType(String contentType) {
    if (contentType == null) {
        return null;
    }
    MediaType mediaType = MediaType.parse(contentType);
    if (mediaType == null) {
        return null;
    }
    return parseCharset(mediaType.getParameters().get("charset"));
}
